418| \section{递推数列}
419| 
420| \begin{method}[研究 $u_{n+1} = f(u_n)$]\label{met:b1:seq:recurrent}
421| 给定 $f$ 与起点 $u_0$：\index{recurrent sequence}
422| \begin{enumerate}
423|   \item \emph{稳定区间：}求区间 $I$，使 $f(I)
424|         \subseteq I$ 且 $u_0 \in I$：则（由归纳法）所有 $u_n \in I$。
425|   \item \emph{候选极限：}若 $u_n \to \ell \in I$，且 $f$ 在 $\ell$ 处连续（\cref{ch:b1:continuity}），则 $\ell$
426|         是一个\emph{不动点}：$f(\ell) = \ell$。解方程 $f(x) = x$。
427|   \item \emph{单调性：}若 $f$ 在 $I$ 上单调递增，则 $(u_n)$ 单调（若 $u_1 \geq u_0$ 则递增，否则递减）；结合有界性，由\cref{thm:b1:seq:monotone} 即可得出结论。若 $f$ 单调递减，则研究两个子列 $(u_{2n})$ 与 $(u_{2n+1})$，它们对 $f \circ f$ 而言是单调的。
428|   \item \emph{误差控制：}若不等式 $\abs{f(x) - \ell} \leq
429|         k\abs{x - \ell}$ 中 $k < 1$，则直接得到 $\abs{u_n - \ell} \leq
430|         k^n \abs{u_0 - \ell} \to 0$。
431| \end{enumerate}
432| \end{method}
